// spec: .qa/e2e/specs/profile.md
// seed: tests/seed.user1.spec.ts
import { test, expect } from '@playwright/test';
import * as path from 'path';

test.use({ storageState: path.resolve(__dirname, '../../../auth/user1.json') });

test.describe('Профиль — вошедший пользователь', () => {
  test('PR-01 «פרופיל אישי» — все предпочтения видны и открываются на правку; «סיסמה» нет #6a86f7f9 @prod-safe', async ({ page }) => {
    // 1. Открыть `/home` → клик по имени → `/profile`.
    await page.goto('/home');
    await page.getByRole('button', { name: 'מעבר לפרטים שלי' }).click();
    await expect(page).toHaveURL(/\/profile$/);

    // 2. Проверить разделы и строки.
    await expect(page.getByRole('heading', { level: 1, name: 'פרופיל אישי' })).toBeVisible();
    await expect(page.getByRole('button', { name: 'חזרה' })).toBeVisible();
    await expect(page.getByRole('button', { name: 'העלאת תמונת פרופיל' })).toBeVisible();
    await expect(page.getByRole('button', { name: 'עריכת השם' })).toBeVisible();
    await expect(page.getByText('gfd13gfg@gmail.com').first()).toBeVisible();

    await expect(page.getByRole('heading', { name: 'פרטים אישיים' })).toBeVisible();
    for (const field of ['נוסח תפילה', 'תאריך לידה', 'מיקום', 'היעד שלי', 'רמת התחזקות']) {
      await expect(page.getByRole('button', { name: new RegExp(`^${field}: .+\\. מעבר לשלב כדי לשנות$`) })).toBeVisible();
    }
    await expect(page.getByRole('heading', { name: 'תאריכים חשובים' })).toBeVisible();
    await expect(page.getByRole('heading', { name: 'פרטי ההרשמה' })).toBeVisible();
    for (const field of ['שם מלא', 'טלפון', 'אימייל']) {
      await expect(page.getByRole('button', { name: new RegExp(`^${field}: .+\\. מעבר לשלב כדי לשנות$`) })).toBeVisible();
    }
    await expect(page.getByRole('heading', { name: 'הגדרות' })).toBeVisible();
    await expect(page.getByRole('switch', { name: /^תזכורות במערכת/ })).toBeVisible();
    await expect(page.getByRole('button', { name: /^הודעות במייל, SMS ו־WhatsApp/ })).toBeVisible();
    await expect(page.getByRole('heading', { name: 'אודות' })).toBeVisible();
    await expect(page.getByRole('button', { name: 'התנתקות' })).toBeVisible(); // не нажимаем

    // Нигде нет слова «סיסמה»; нет горизонтальной прокрутки
    await expect(page.locator('body')).not.toContainText('סיסמה');
    const noHScroll = () =>
      page.evaluate(() => document.documentElement.scrollWidth <= document.documentElement.clientWidth);
    expect(await noHScroll()).toBe(true);

    // 3. Открыть «רמת התחזקות»: slider, стрелка, aria-valuetext; закрыть «סגירה» без сохранения.
    await page.getByRole('button', { name: /^רמת התחזקות: / }).click();
    const dialog = page.getByRole('dialog');
    const slider = dialog.getByRole('slider', { name: 'רמת ההתחזקות' });
    await expect(slider).toBeVisible();
    await expect(slider).toHaveAttribute('aria-valuemin', '1');
    await expect(slider).toHaveAttribute('aria-valuemax', '7');
    await expect(slider).toHaveAttribute('aria-valuetext', 'כל יום');
    await expect(dialog.getByText('פעם בשבוע', { exact: true })).toBeVisible();
    await expect(dialog.getByText('כל יום', { exact: true }).last()).toBeVisible();
    await expect(dialog.getByRole('button', { name: 'שמירה' })).toBeDisabled();
    await slider.focus();
    await page.keyboard.press('ArrowRight'); // RTL: стрелка вправо уменьшает
    await expect(slider).toHaveAttribute('aria-valuetext', '6 פעמים בשבוע');
    await expect(dialog.getByRole('button', { name: 'שמירה' })).toBeEnabled();
    await dialog.getByRole('button', { name: 'סגירה' }).click();
    await expect(page.getByRole('dialog')).toHaveCount(0);
    await expect(page.getByRole('button', { name: 'רמת התחזקות: כל יום. מעבר לשלב כדי לשנות' })).toBeVisible();

    // 4. Открыть «נוסח תפילה»: radio; закрыть «סגירה» без сохранения.
    await page.getByRole('button', { name: /^נוסח תפילה: / }).click();
    await expect(page.getByRole('radio', { name: /^נוסח אשכנז/ })).toHaveAttribute('aria-checked', 'true');
    await expect(page.getByRole('radio', { name: /^נוסח ספרד/ })).toHaveAttribute('aria-checked', 'false');
    const east = page.getByRole('radio', { name: /^נוסח עדות המזרח/ });
    await expect(east).toHaveAttribute('aria-disabled', 'true');
    await expect(east).toContainText('בקרוב');
    await page.getByRole('dialog').getByRole('button', { name: 'סגירה' }).click();
    await expect(page.getByRole('dialog')).toHaveCount(0);
    await expect(page.getByRole('button', { name: 'נוסח תפילה: אשכנז. מעבר לשלב כדי לשנות' })).toBeVisible();

    expect(await noHScroll()).toBe(true);
  });
});
